import math

def is_perfect_cube(n):
    if n == 0:
        return True
    # Calculate the cube root and round it to the nearest integer
    root = round(abs(n)**(1/3))
    # Check if the cube of the root matches the absolute value of n
    if root**3 == abs(n):
        # If n is negative, the cube root must be negative
        if n < 0:
            return (-root)**3 == n
        else:
            return root**3 == n
    return False

solutions = []
for x in range(-10, 11):
    # Calculate the expression E(x) = (8x - 41)(x + 3)^2
    term1 = 8 * x - 41
    term2 = (x + 3)**2
    E_x = term1 * term2

    if is_perfect_cube(E_x):
        solutions.append((x, E_x))

print("Solutions found (x, E(x)):")
